1. #!/usr/bin/env node
2. // Cross-tool plugin validation: symlinks, SKILL.md frontmatter, no personal leaks
3. 'use strict';
4. const fs = require('fs');
5. const path = require('path');
6. const root = path.resolve(__dirname, '..');
7. let errors = 0;
8. 
9. // 1. Root plugin.json valid
10. const plugin = JSON.parse(fs.readFileSync(path.join(root, 'plugin.json'), 'utf8'));
11. console.log(`✅ plugin.json: name="${plugin.name}", ${plugin.skills.length} skills`);
12. 
13. // 2. Symlinks exist and are symlinks (not copies)
14. for (const rel of ['.claude-plugin/plugin.json', '.github/plugin/plugin.json']) {
15.   const full = path.join(root, rel);
16.   if (!fs.existsSync(full)) { console.error(`❌ Missing: ${rel}`); errors++; continue; }
17.   const stat = fs.lstatSync(full);
18.   if (!stat.isSymbolicLink()) { console.error(`❌ Not a symlink: ${rel}`); errors++; continue; }
19.   const content = JSON.parse(fs.readFileSync(full, 'utf8'));
20.   if (content.name !== plugin.name) { console.error(`❌ ${rel} name mismatch`); errors++; continue; }
21.   console.log(`✅ ${rel}: symlink resolves, name matches`);
22. }
23. 
24. // 3. Every plugin skill has SKILL.md with frontmatter
25. for (const skillPath of plugin.skills) {
26.   const md = path.join(root, skillPath, 'SKILL.md');
27.   if (!fs.existsSync(md)) { console.error(`❌ Missing SKILL.md: ${skillPath}`); errors++; continue; }
28.   const text = fs.readFileSync(md, 'utf8');
29.   if (!text.startsWith('---')) {
30.     // Frontmatter optional per spec but recommended
31.     console.log(`⚠️  No frontmatter: ${skillPath} (optional)`);
32.   }
33. }
34. console.log(`✅ All ${plugin.skills.length} skills have SKILL.md`);
35. 
36. // 4. No personal skills in plugin.json
37. const triage = JSON.parse(fs.readFileSync(path.join(root, 'skills', '.plugin-triage.json'), 'utf8'));
38. const personalNames = new Set(triage.personal.map(p => p.name));
39. for (const s of plugin.skills) {
40.   const name = s.replace('skills/', '');
41.   if (personalNames.has(name)) { console.error(`❌ Personal skill leaked: ${name}`); errors++; }
42. }
43. console.log('✅ No personal skills in plugin manifest');
44. 
45. // 5. Wiki seed manifest exists
46. const seedPath = path.join(root, 'wiki', '.seed-manifest.json');
47. if (fs.existsSync(seedPath)) {
48.   const seed = JSON.parse(fs.readFileSync(seedPath, 'utf8'));
49.   const total = seed.concepts.length + seed.sources.length;
50.   console.log(`✅ Wiki seed: ${total} articles`);
51. } else { console.error('❌ Missing wiki/.seed-manifest.json'); errors++; }
52. 
53. if (errors) { console.error(`\n${errors} error(s)`); process.exit(1); }
54. console.log('\n✅ Cross-tool validation passed');
55.

