from pathlib import Path
import yaml
root = Path('/home/curtisfranks/.copilot/skills')
files = sorted(root.glob('*/SKILL.md'))
fail = []
missing = []
for f in files:
    text = f.read_text()
    if not text.startswith('---\n'):
        fail.append((str(f), 'missing opening frontmatter'))
        continue
    try:
        _, fm, _ = text.split('---\n', 2)
    except ValueError:
        fail.append((str(f), 'frontmatter split failed'))
        continue
    try:
        data = yaml.safe_load(fm) or {}
    except Exception as e:
        fail.append((str(f), str(e).split('\n')[0]))
        continue
    req = ['name','description','argument-hint','user-invocable','disable-model-invocation']
    miss = [k for k in req if k not in data]
    if miss:
        missing.append((str(f), ','.join(miss)))
print('FILES', len(files))
print('PARSE_FAIL', len(fail))
for p,e in fail:
    print('FAIL', p, '::', e)
print('MISSING', len(missing))
for p,e in missing:
    print('MISS', p, '::', e)
