    miss = [k for k in req if k not in data]
    if miss:
        missing.append((str(f), ','.join(miss)))
print('FILES', len(files))
print('PARSE_FAIL', len(fail))
for p,e in fail:
    print('FAIL', p, '::', e)
print('MISSING', len(missing))
